using System;
using System.Collections.Generic;
using UnityEngine;
using Framework.Save;
using Framework.Save.Integrations.EasySave;

namespace Game.Tests
{
    /// <summary>
    /// EasySaveProviderの動作確認用クラス。
    ///
    /// データの保存・読み込み・上書き・削除、
    /// 保存ファイルの独立性などを検証する。
    /// </summary>
    public class EasySaveProviderTest : MonoBehaviour
    {
        #region Test Data Types

        /// <summary>
        /// 独自クラスの保存を検証するためのデータ型。
        /// </summary>
        [Serializable]
        public class SampleSaveData
        {
            /// <summary>テスト用の所持宝石数。</summary>
            public int GemCount;

            /// <summary>テスト用の装備レベル。</summary>
            public int EquipmentLevel;

            /// <summary>テスト用のプレイヤー名。</summary>
            public string PlayerName;

            /// <summary>テスト用のクリア状態。</summary>
            public bool IsCleared;
        }

        #endregion

        #region Inspector Fields

        [Header("テスト設定")]

        /// <summary>開始時に自動テストを実行するか。</summary>
        [SerializeField]
        [Tooltip("開始時に全自動テストを実行する")]
        private bool runTestsOnStart = true;

        /// <summary>テスト終了時に保存ファイルを削除するか。</summary>
        [SerializeField]
        [Tooltip("テスト終了時にテスト専用ファイルを削除する")]
        private bool deleteFilesAfterTest = true;

        #endregion

        #region Runtime Fields

        /// <summary>メインのテスト用保存Provider。</summary>
        private EasySaveProvider provider;

        /// <summary>保存領域の独立性確認用Provider。</summary>
        private EasySaveProvider secondaryProvider;

        /// <summary>成功したテスト項目数。</summary>
        private int passedCount;

        /// <summary>失敗したテスト項目数。</summary>
        private int failedCount;

        #endregion

        #region Unity Methods

        /// <summary>シーン開始時の処理。</summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        #endregion

        #region Test Control Methods

        /// <summary>すべての自動テストを実行する。</summary>
        [ContextMenu("テスト/全自動テストを実行する")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "再生モードで実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                CreateTestProviders();

                TestInitialState();
                TestPrimitiveTypes();
                TestOverwrite();
                TestMissingData();
                TestTryLoad();
                TestCollections();
                TestCustomData();
                TestFilePersistence();
                TestDelete();
                TestFileIsolation();
                TestFlush();
                TestInvalidArguments();
                TestDeleteAll();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                if (deleteFilesAfterTest)
                {
                    CleanupTestFiles();
                }

                PrintTestResult();
            }
        }

        /// <summary>
        /// テスト専用の保存Providerを生成する。
        /// </summary>
        private void CreateTestProviders()
        {
            // 本番データや他のテストと競合しないように、
            // 実行ごとに固有のファイル名を生成する。
            string testId = Guid.NewGuid().ToString("N");

            provider = new EasySaveProvider(
                $"Tests/EasySave_{testId}_Main.es3");

            secondaryProvider = new EasySaveProvider(
                $"Tests/EasySave_{testId}_Secondary.es3");

            Debug.Log(
                $"テスト用保存ファイル：\n" +
                $"{provider.FilePath}\n" +
                $"{secondaryProvider.FilePath}",
                this);
        }

        /// <summary>テスト専用ファイルを削除する。</summary>
        private void CleanupTestFiles()
        {
            CleanupProvider(provider);
            CleanupProvider(secondaryProvider);
        }

        /// <summary>
        /// 指定されたテスト用Providerのファイルを削除する。
        /// </summary>
        /// <param name="target">削除対象のProvider</param>
        private void CleanupProvider(EasySaveProvider target)
        {
            if (target == null)
            {
                return;
            }

            try
            {
                target.DeleteAll();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
        }

        #endregion

        #region Test Methods

        /// <summary>初期状態を検証する。</summary>
        private void TestInitialState()
        {
            Check(
                !string.IsNullOrWhiteSpace(provider.FilePath),
                "保存ファイルパスの保持");

            Check(
                !provider.FileExists(),
                "初期状態のファイル未作成");

            Check(
                !provider.Exists("UnknownKey"),
                "未保存キーの存在確認");
        }

        /// <summary>基本データ型の保存を検証する。</summary>
        private void TestPrimitiveTypes()
        {
            provider.Save("IntValue", 150);
            provider.Save("FloatValue", 0.75f);
            provider.Save("BoolValue", true);
            provider.Save("StringValue", "Easy Save Test");

            Check(
                provider.FileExists(),
                "保存ファイルの生成");

            Check(
                provider.Exists("IntValue"),
                "保存キーの存在確認");

            Check(
                provider.Load("IntValue", 0) == 150,
                "int型の保存・読み込み");

            Check(
                Mathf.Approximately(
                    provider.Load("FloatValue", 0f),
                    0.75f),
                "float型の保存・読み込み");

            Check(
                provider.Load("BoolValue", false),
                "bool型の保存・読み込み");

            Check(
                provider.Load("StringValue", "") ==
                "Easy Save Test",
                "string型の保存・読み込み");
        }

        /// <summary>既存データの上書きを検証する。</summary>
        private void TestOverwrite()
        {
            provider.Save("OverwriteValue", 100);
            provider.Save("OverwriteValue", 250);

            Check(
                provider.Load("OverwriteValue", 0) == 250,
                "既存データの上書き");

            Check(
                provider.Load("IntValue", 0) == 150,
                "上書き時の他データ維持");
        }

        /// <summary>未保存データの読み込みを検証する。</summary>
        private void TestMissingData()
        {
            Check(
                provider.Load("MissingInt", 999) == 999,
                "未保存int型の初期値");

            Check(
                Mathf.Approximately(
                    provider.Load("MissingFloat", 0.5f),
                    0.5f),
                "未保存float型の初期値");

            Check(
                provider.Load("MissingBool", true),
                "未保存bool型の初期値");

            Check(
                provider.Load("MissingString", "Default") ==
                "Default",
                "未保存string型の初期値");
        }

        /// <summary>安全な読み込み処理を検証する。</summary>
        private void TestTryLoad()
        {
            Check(
                provider.TryLoad<int>(
                    "IntValue",
                    out int intValue),
                "TryLoadによる読み込み成功");

            Check(
                intValue == 150,
                "TryLoadの読み込み結果");

            Check(
                !provider.TryLoad<int>(
                    "MissingInt",
                    out int missingInt),
                "未保存データのTryLoad失敗");

            Check(
                missingInt == 0,
                "TryLoad失敗時の値型既定値");

            Check(
                !provider.TryLoad<string>(
                    "MissingString",
                    out string missingString),
                "未保存参照型のTryLoad失敗");

            Check(
                missingString == null,
                "TryLoad失敗時の参照型既定値");
        }

        /// <summary>コレクション型の保存を検証する。</summary>
        private void TestCollections()
        {
            // 配列型の保存。
            int[] array = { 10, 20, 30 };

            provider.Save("ArrayValue", array);

            int[] loadedArray = provider.Load<int[]>(
                "ArrayValue",
                null);

            Check(
                loadedArray != null &&
                loadedArray.Length == 3,
                "配列型の保存・読み込み");

            Check(
                loadedArray != null &&
                loadedArray.Length == 3 &&
                loadedArray[0] == 10 &&
                loadedArray[1] == 20 &&
                loadedArray[2] == 30,
                "配列内のデータ維持");

            // List型の保存。
            List<string> list = new List<string>
            {
                "Gem",
                "Magnet",
                "Shield"
            };

            provider.Save("ListValue", list);

            List<string> loadedList =
                provider.Load<List<string>>(
                    "ListValue",
                    null);

            Check(
                loadedList != null &&
                loadedList.Count == 3,
                "List型の保存・読み込み");

            Check(
                loadedList != null &&
                loadedList.Count == 3 &&
                loadedList[0] == "Gem" &&
                loadedList[1] == "Magnet" &&
                loadedList[2] == "Shield",
                "List内のデータ維持");

            // Dictionary型の保存。
            Dictionary<string, int> dictionary =
                new Dictionary<string, int>
                {
                    { "Magnet", 3 },
                    { "Shield", 2 }
                };

            provider.Save("DictionaryValue", dictionary);

            Dictionary<string, int> loadedDictionary =
                provider.Load<Dictionary<string, int>>(
                    "DictionaryValue",
                    null);

            Check(
                loadedDictionary != null &&
                loadedDictionary.Count == 2,
                "Dictionary型の保存・読み込み");

            Check(
                loadedDictionary != null &&
                loadedDictionary.TryGetValue(
                    "Magnet",
                    out int magnetLevel) &&
                magnetLevel == 3 &&
                loadedDictionary.TryGetValue(
                    "Shield",
                    out int shieldLevel) &&
                shieldLevel == 2,
                "Dictionary内のデータ維持");
        }

        /// <summary>独自クラスの保存を検証する。</summary>
        private void TestCustomData()
        {
            SampleSaveData data = new SampleSaveData
            {
                GemCount = 500,
                EquipmentLevel = 4,
                PlayerName = "天禄",
                IsCleared = true
            };

            provider.Save("CustomData", data);

            SampleSaveData loadedData =
                provider.Load<SampleSaveData>(
                    "CustomData",
                    null);

            Check(
                loadedData != null,
                "独自クラスの保存・読み込み");

            Check(
                loadedData != null &&
                loadedData.GemCount == 500,
                "独自クラス内のint型");

            Check(
                loadedData != null &&
                loadedData.EquipmentLevel == 4,
                "独自クラス内の装備レベル");

            Check(
                loadedData != null &&
                loadedData.PlayerName == "天禄",
                "独自クラス内の日本語文字列");

            Check(
                loadedData != null &&
                loadedData.IsCleared,
                "独自クラス内のbool型");
        }

        /// <summary>
        /// Providerを再生成しても保存データを取得できるか
        /// 検証する。
        /// </summary>
        private void TestFilePersistence()
        {
            provider.Save("PersistentValue", 12345);

            // 同じ保存ファイルを参照するProviderを生成する。
            ISaveProvider newProvider =
                new EasySaveProvider(provider.FilePath);

            Check(
                newProvider.Exists("PersistentValue"),
                "Provider再生成後のデータ存在確認");

            Check(
                newProvider.Load("PersistentValue", 0) ==
                12345,
                "Provider再生成後のデータ読み込み");
        }

        /// <summary>個別データの削除を検証する。</summary>
        private void TestDelete()
        {
            provider.Save("DeleteTarget", 100);
            provider.Save("KeepTarget", 200);

            provider.Delete("DeleteTarget");

            Check(
                !provider.Exists("DeleteTarget"),
                "指定キーの削除");

            Check(
                provider.Load("DeleteTarget", -1) == -1,
                "削除後の初期値取得");

            Check(
                provider.Load("KeepTarget", 0) == 200,
                "個別削除時の他データ維持");

            CheckNoException(
                () => provider.Delete("UnknownDeleteKey"),
                "未保存キーの削除");
        }

        /// <summary>保存ファイルの独立性を検証する。</summary>
        private void TestFileIsolation()
        {
            provider.Save("SharedKey", 100);
            secondaryProvider.Save("SharedKey", 200);

            Check(
                provider.Load("SharedKey", 0) == 100,
                "メインファイルの独立性");

            Check(
                secondaryProvider.Load("SharedKey", 0) == 200,
                "サブファイルの独立性");

            secondaryProvider.DeleteAll();

            Check(
                !secondaryProvider.FileExists(),
                "サブファイルの全削除");

            Check(
                provider.FileExists(),
                "他ファイル削除時のファイル維持");

            Check(
                provider.Load("SharedKey", 0) == 100,
                "他ファイル削除時のデータ維持");
        }

        /// <summary>保存確定処理を検証する。</summary>
        private void TestFlush()
        {
            provider.Save("FlushValue", 789);

            CheckNoException(
                () => provider.Flush(),
                "Flushの安全な実行");

            Check(
                provider.Load("FlushValue", 0) == 789,
                "Flush後の保存データ維持");
        }

        /// <summary>不正な引数の検証を行う。</summary>
        private void TestInvalidArguments()
        {
            CheckThrows<ArgumentException>(
                () => new EasySaveProvider(null),
                "nullファイルパスの拒否");

            CheckThrows<ArgumentException>(
                () => new EasySaveProvider(""),
                "空ファイルパスの拒否");

            CheckThrows<ArgumentException>(
                () => new EasySaveProvider("   "),
                "空白ファイルパスの拒否");

            CheckThrows<ArgumentException>(
                () => provider.Save<int>(null, 100),
                "null保存キーの拒否");

            CheckThrows<ArgumentException>(
                () => provider.Load("", 0),
                "空読み込みキーの拒否");

            CheckThrows<ArgumentException>(
                () => provider.TryLoad<int>(" ", out _),
                "空白TryLoadキーの拒否");

            CheckThrows<ArgumentException>(
                () => provider.Exists(null),
                "不正な存在確認キーの拒否");

            CheckThrows<ArgumentException>(
                () => provider.Delete(""),
                "不正な削除キーの拒否");
        }

        /// <summary>保存ファイルの全削除を検証する。</summary>
        private void TestDeleteAll()
        {
            provider.DeleteAll();

            Check(
                !provider.FileExists(),
                "保存ファイルの全削除");

            Check(
                !provider.Exists("IntValue"),
                "全削除後のキー消失");

            Check(
                provider.Load("IntValue", -1) == -1,
                "全削除後の初期値取得");

            CheckNoException(
                () => provider.DeleteAll(),
                "存在しないファイルの全削除");

            // 全削除後もProviderを再利用できるか確認する。
            provider.Save("RecreatedValue", 42);

            Check(
                provider.FileExists(),
                "全削除後のファイル再生成");

            Check(
                provider.Load("RecreatedValue", 0) == 42,
                "全削除後のProvider再利用");
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 指定された例外が発生するか確認する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">実行する処理</param>
        /// <param name="testName">テスト項目名</param>
        private void CheckThrows<TException>(
            Action action,
            string testName)
            where TException : Exception
        {
            try
            {
                action();

                Check(false, testName);
            }
            catch (TException)
            {
                Check(true, testName);
            }
            catch (Exception exception)
            {
                Check(
                    false,
                    $"{testName}：{exception.GetType().Name}");
            }
        }

        /// <summary>
        /// 例外が発生せずに処理を実行できるか確認する。
        /// </summary>
        /// <param name="action">実行する処理</param>
        /// <param name="testName">テスト項目名</param>
        private void CheckNoException(
            Action action,
            string testName)
        {
            try
            {
                action();

                Check(true, testName);
            }
            catch (Exception exception)
            {
                Check(
                    false,
                    $"{testName}：{exception.Message}");
            }
        }

        /// <summary>テスト結果を記録する。</summary>
        /// <param name="condition">成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        /// <summary>テストの集計結果を出力する。</summary>
        private void PrintTestResult()
        {
            string message =
                "【EasySaveProvider テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message +
                    "\nすべてのテストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

        #endregion
    }
}
